-- symbiosis, the ttt plugin. GENERATED by ttt/build.ts from ttt/src: do not
-- edit this file; edit ttt/src and run `npm run build`.
-- Lines of this file, by source (for errors in ttt's log):
--      38  ttt/src/core/app.lua
--     359  ttt/src/core/buffer.lua
--     407  ttt/src/core/channel.lua
--     517  ttt/src/core/settings.lua
--     640  ttt/src/core/util.lua
--     783  ttt/src/features/autosave.lua
--     831  ttt/src/features/changes.lua
--     877  ttt/src/features/helpi.lua
--    1298  ttt/src/features/marks.lua
--    1373  ttt/src/features/panel.lua
--    1441  ttt/src/features/plan.lua
--    1544  ttt/src/features/replay.lua
--    2051  ttt/src/features/sessions.lua
--    2297  ttt/src/features/tree.lua
--    2434  ttt/src/main.lua
local modules, loaded, loading = {}, {}, {}
local host_require = require
-- The bundle's require: a module in the bundle, else one of ttt's.
local function require(name)
	local value = loaded[name]
	if value ~= nil then return value end
	local load = modules[name]
	if not load then return host_require(name) end
	if loading[name] then error("modules require each other: " .. name, 2) end
	loading[name] = true
	local ok, result = pcall(load, name)
	loading[name] = nil
	if not ok then error(result, 0) end
	value = result
	if value == nil then value = true end
	loaded[name] = value
	return value
end
modules["core.app"] = function(...)
-- The host. The plugin is a set of features (ttt/src/features/*.lua); each
-- one plugs into the host and talks to the others only through it.
--
-- A feature is a table:
--
--   return {
--     name = "plan",
--     needs = { "sessions" },        -- features set up before this one
--     setup = function(app)
--       local sessions = app:need("sessions")  -- the api `sessions` returned
--       app:on("sessions", function() ... end)
--       app:command({ id = "symbiosis.showPlan", title = "...", key = "ctrl+k v", run = open })
--       return { open = open }      -- this feature's api, for app:need("plan")
--     end,
--   }
--
-- main.lua: app:use("features.plan") for each feature, then app:start().
--
-- What the host gives a feature:
--   app:need(name) / app:get(name)  another feature's api (get: nil if absent)
--   app:on(hook, fn, order)         a hook; lower `order` first (default 50)
--   app:emit(hook, ...)             runs a hook's handlers
--   app:command(def)                a command, with an optional key
--   app:hint(def)                   a line in the panel's key list
--   app:sidebar(def)                the sidebar panel (one for the plugin)
--   app:section(def)                a section of the panel (ctrl+k h)
--   app:note(text, order)           a muted line at the end of the panel
--   app.settings                    core/settings.lua
--   app.channel                     core/channel.lua: pi's events, heartbeat
--   app.loaded, app.ticks           the editor API is usable; poll ticks
--
-- Hooks the host runs:
--   ready            once, 100 ms after load: fs and the status bar work now
--   tick             every POLL_MS (40 ms)
--   second           every second
--   key (key)        a key press; a handler that returns true takes the key
--   file             a file opened or the tab changed (after ready)
--   change           the buffer changed
--   drop (name)      feature `name` failed and is dropped: forget what you keep for it
-- Features emit their own hooks too: "sessions", "owner", "follow" ...
--
-- A feature whose setup fails is dropped with all it registered, and so are
-- the features that need it; the others run. A hook handler that fails is
-- logged; the next handler runs.
local ttt = require("ttt")
local events = require("ttt.events")
local buffer = require("core.buffer")
local settings = require("core.settings")
local channel = require("core.channel")

local M = { POLL_MS = 40 }

local App = {}
App.__index = App

-- opts.dir: the plugin folder (its files: the channel, settings.json).
function M.new(opts)
	opts = opts or {}
	local app = setmetatable({
		dir = opts.dir or ttt.plugin_dir(),
		features = {}, by_name = {}, apis = {}, failed = {},
		hooks = {}, commands = {}, hints = {}, sections = {}, notes = {}, side = nil,
		current = "core", seq = 0, loaded = false, ticks = 0,
	}, App)
	local function owner() return app.current end
	app.log = opts.log or function(level, message) ttt.log(level, message) end
	app.settings = settings.new(app.dir .. "/settings.json", owner)
	app.channel = channel.new(app.dir, app.log, owner)
	return app
end

-- Features -------------------------------------------------------------------

-- `feature`: the table, or the name of its module ("features.plan"). A
-- module that fails to load is a feature that failed: the others run.
function App:use(feature)
	if type(feature) == "string" then
		local ok, mod = pcall(require, feature)
		if not ok then
			local name = feature:match("[^.]+$")
			self.failed[name] = tostring(mod)
			self.log("error", "symbiosis: feature " .. name .. " is off: " .. tostring(mod))
			return self
		end
		feature = mod
	end
	if type(feature) ~= "table" or type(feature.name) ~= "string" or type(feature.setup) ~= "function" then
		error("a feature is a table with a name and a setup function", 2)
	end
	if self.by_name[feature.name] then error("feature " .. feature.name .. " is used twice", 2) end
	self.by_name[feature.name] = feature
	table.insert(self.features, feature)
	return self
end

function App:get(name) return self.apis[name] end

function App:need(name)
	local api = self.apis[name]
	if api == nil then error("feature " .. self.current .. " needs " .. name .. ", which is not set up", 2) end
	return api
end

-- The features in the order they set up: each after the ones it needs, else
-- in the order of use(). Returns the order, and name -> why for the features
-- that cannot set up: a need that is not used (or failed to load), or a cycle.
function App:order()
	local out, state, bad = {}, {}, {}
	local function visit(f, path)
		if state[f.name] == "done" then return end
		if state[f.name] == "visiting" then
			bad[f.name] = "features need each other: " .. path .. " → " .. f.name
			return
		end
		state[f.name] = "visiting"
		for _, n in ipairs(f.needs or {}) do
			local dep = self.by_name[n]
			if not dep then
				bad[f.name] = bad[f.name] or ("needs " .. n .. ", which " .. (self.failed[n] and "failed" or "is not used"))
			else
				visit(dep, path == "" and f.name or (path .. " → " .. f.name))
			end
		end
		state[f.name] = "done"
		table.insert(out, f)
	end
	for _, f in ipairs(self.features) do visit(f, "") end
	return out, bad
end

-- Drops all that `name` registered.
function App:drop(name)
	local function keep(list)
		local out = {}
		for _, e in ipairs(list) do
			if e.owner ~= name then table.insert(out, e) end
		end
		return out
	end
	for hook, list in pairs(self.hooks) do self.hooks[hook] = keep(list) end
	self.commands, self.hints = keep(self.commands), keep(self.hints)
	self.sections, self.notes = keep(self.sections), keep(self.notes)
	if self.side and self.side.owner == name then self.side = nil end
	self.settings:drop(name)
	self.channel:drop(name)
	-- The other features drop what they keep for it (see replay.hold).
	self:emit("drop", name)
end

-- Sets up each feature. Returns the names of those that failed.
function App:setup()
	local order, bad = self:order()
	for _, f in ipairs(order) do
		local missing = nil
		for _, n in ipairs(f.needs or {}) do
			if self.apis[n] == nil then missing = n break end
		end
		if bad[f.name] then
			self.failed[f.name] = bad[f.name]
		elseif missing then
			self.failed[f.name] = "needs " .. missing .. ", which failed"
		else
			self.current = f.name
			local ok, api = pcall(f.setup, self)
			self.current = "core"
			if ok then
				self.apis[f.name] = api or {}
			else
				self:drop(f.name)
				self.failed[f.name] = tostring(api)
			end
		end
		if self.failed[f.name] then
			self.log("error", "symbiosis: feature " .. f.name .. " is off: " .. self.failed[f.name])
		end
	end
	return self.failed
end

-- Registries -------------------------------------------------------------------

local function entry(app, e)
	app.seq = app.seq + 1
	e.owner, e.seq = app.current, app.seq
	return e
end

local function sorted(list)
	table.sort(list, function(a, b)
		if a.order ~= b.order then return a.order < b.order end
		return a.seq < b.seq
	end)
end

function App:on(hook, fn, order)
	local list = self.hooks[hook] or {}
	self.hooks[hook] = list
	table.insert(list, entry(self, { fn = fn, order = order or 50 }))
	sorted(list)
end

local function failed(app, e, what, err)
	buffer.editing = false
	app.log("error", "symbiosis " .. tostring(e.owner) .. " " .. what .. ": " .. tostring(err))
end

-- Runs every handler of `hook`.
function App:emit(hook, ...)
	for _, e in ipairs(self.hooks[hook] or {}) do
		local ok, err = pcall(e.fn, ...)
		if not ok then failed(self, e, hook, err) end
	end
end

-- Runs the handlers of `hook` until one returns true; then returns true.
function App:first(hook, ...)
	for _, e in ipairs(self.hooks[hook] or {}) do
		local ok, taken = pcall(e.fn, ...)
		if not ok then failed(self, e, hook, taken)
		elseif taken == true then return true end
	end
	return false
end

-- def: { id, title, run, key = "ctrl+k x" (optional) }
function App:command(def)
	if type(def.id) ~= "string" or type(def.run) ~= "function" then error("a command needs an id and run", 2) end
	for _, c in ipairs(self.commands) do
		if c.id == def.id then error("command " .. def.id .. " is taken by " .. tostring(c.owner), 2) end
	end
	table.insert(self.commands, entry(self, { id = def.id, title = def.title or def.id, key = def.key, run = def.run, order = 0 }))
end

-- def: { key = "ctrl+k v", text = "pi's plan", order = 70 }
function App:hint(def)
	table.insert(self.hints, entry(self, { key = def.key, value = def.text, order = def.order or 50 }))
	sorted(self.hints)
end

-- def: { title, render(panel) }. ttt has one sidebar panel for each plugin.
function App:sidebar(def)
	if self.side then error("the sidebar is taken by " .. tostring(self.side.owner), 2) end
	self.side = entry(self, { title = def.title, render = def.render })
end

-- def: { render(panel), order }. The panel (ctrl+k h) draws the sections in order.
function App:section(def)
	table.insert(self.sections, entry(self, { render = def.render, order = def.order or 50 }))
	sorted(self.sections)
end

function App:note(text, order)
	table.insert(self.notes, entry(self, { text = text, order = order or 50 }))
	sorted(self.notes)
end

-- Start ------------------------------------------------------------------------

-- What ttt.register gets: the sidebar, the commands and their keys.
function App:registration()
	local reg = { commands = {}, keybindings = {} }
	if self.side then reg.sidebar = { title = self.side.title, render = self.side.render } end
	for _, c in ipairs(self.commands) do
		local cmd = c
		table.insert(reg.commands, {
			id = cmd.id,
			title = cmd.title,
			handler = function(...)
				local ok, err = pcall(cmd.run, ...)
				if not ok then failed(self, cmd, cmd.id, err) end
			end,
		})
		if cmd.key then table.insert(reg.keybindings, { key = cmd.key, command = cmd.id }) end
	end
	return reg
end

-- Sets up the features, registers them with ttt, and starts the clock.
function App:start()
	local channel = self.channel
	self:on("tick", function() channel:poll() end, 0)
	self:on("ready", function() channel:heartbeat() end, 90)
	self:on("second", function() channel:heartbeat() end, 90)
	self:setup()
	ttt.register(self:registration())

	events.on("key.press", function(key)
		if buffer.editing then return false end
		return self:first("key", key)
	end)
	local function on_file()
		if self.loaded then self:emit("file") end
	end
	events.on("file.open", on_file)
	events.on("tab.change", on_file)
	events.on("editor.change", function() self:emit("change") end)

	-- fs.read and the status bar are not ready while the plugin loads.
	ttt.set_timeout(100, function()
		self.loaded = true
		local ok, err = pcall(self.settings.load, self.settings)
		if not ok then self.log("error", "symbiosis settings.json: " .. tostring(err)) end
		self:emit("ready")
		local off = {}
		for name in pairs(self.failed) do table.insert(off, name) end
		if #off > 0 then
			table.sort(off)
			ttt.notify("symbiosis: off after an error: " .. table.concat(off, ", ") .. " (see ttt's log)", "error")
		end
		ttt.set_interval(M.POLL_MS, function()
			self.ticks = self.ticks + 1
			self:emit("tick")
		end)
		ttt.set_interval(1000, function() self:emit("second") end)
	end)
	return self
end

return M
end
modules["core.buffer"] = function(...)
-- The buffer, as the features change it. `editing` is true while a feature
-- changes the buffer: the key handler and the change events ignore those
-- changes (they are the plugin's own, not yours).
local ttt = require("ttt")
local editor = require("ttt.editor")
local util = require("core.util")

local M = { editing = false }

-- Scrolls so that `line` is on screen, in the middle when it was not.
function M.reveal(line)
	local v = editor.viewport()
	if line < v.top_line or line > v.bottom_line - 1 then
		editor.scroll_to(math.max(1, line - math.floor(v.height / 2)))
	end
end

-- Regions: a stretch of the buffer that a feature owns: {line, col, text}.
-- Makes the region read `text`: replaces only what changed after the common
-- prefix. The cursor goes to its end, or `below` lines under its end.
function M.set_region(r, text, below)
	local p = util.prefix(r.text, text)
	local pl, pc = util.after(r.line, r.col, r.text:sub(1, p))
	local el, ec = util.after(r.line, r.col, r.text)
	M.editing = true
	editor.replace(pl, pc, el, ec, text:sub(p + 1))
	M.editing = false
	r.text = text
	local cl, cc = util.after(r.line, r.col, text)
	if below then cl, cc = cl + below.lines, below.col end
	editor.set_cursor(cl, cc)
	M.reveal(cl)
end

-- The text of the whole buffer, as a region: line 1, column 1 to the end.
function M.whole()
	return { line = 1, col = 1, text = editor.buffer_text() }
end

-- Opens `path` when it is not the open file. True when it is open now.
function M.on_buffer(path)
	if editor.file_path() ~= path then ttt.open_file(path) end
	return editor.file_path() == path
end

return M
end
modules["core.channel"] = function(...)
-- The channel to pi: files in the plugin folder (see docs/design.md).
--
--   head.json, events.jsonl   pi appends events; poll() reads the new ones
--                             and hands each to the handler of its `op`
--   ttt.json                  the heartbeat: the features add their fields
--   ack.json, help.json, ...  written by the features through write_json
--
-- A feature takes the events it handles: channel:on("start", fn). One
-- handler for each op; events no feature handles are skipped.
local fs = require("ttt.fs")
local json = require("ttt.json")
local util = require("core.util")

local M = {
	PROTOCOL = 10, -- the channel protocol of core/protocol.ts
}

local Channel = {}
Channel.__index = Channel

-- `log(level, message)`, `owner()`: the feature that registers now.
function M.new(dir, log, owner)
	return setmetatable({
		dir = dir, log = log, owner = owner or function() return nil end,
		handlers = {}, fields = {}, gen = nil, offset = 0,
	}, Channel)
end

function Channel:path(name) return self.dir .. "/" .. name end

function Channel:read_json(name)
	local ok, v = pcall(json.decode, fs.read(self:path(name)) or "")
	if ok then return v end
	return nil
end

function Channel:write_json(name, value)
	fs.write(self:path(name), json.encode(value))
end

-- The handler for pi's events with this `op`.
function Channel:on(op, fn)
	if self.handlers[op] then
		error("the channel op " .. op .. " is taken by " .. tostring(self.handlers[op].owner), 2)
	end
	self.handlers[op] = { fn = fn, owner = self.owner() }
end

-- `fn(fields)` adds its fields to each heartbeat.
function Channel:heartbeat_field(fn)
	table.insert(self.fields, { fn = fn, owner = self.owner() })
end

-- Drops what a feature registered (its setup failed).
function Channel:drop(owner)
	for op, h in pairs(self.handlers) do
		if h.owner == owner then self.handlers[op] = nil end
	end
	local keep = {}
	for _, f in ipairs(self.fields) do
		if f.owner ~= owner then table.insert(keep, f) end
	end
	self.fields = keep
end

function Channel:handles(op) return self.handlers[op] ~= nil end

-- ttt.json: pi reads it to know the editor runs, and the features' fields.
function Channel:heartbeat()
	local rec = { t = os.time() }
	for _, f in ipairs(self.fields) do
		local ok, err = pcall(f.fn, rec)
		if not ok then self.log("error", "symbiosis " .. tostring(f.owner) .. " heartbeat: " .. tostring(err)) end
	end
	fs.write(self:path("ttt.json"), json.encode(rec))
end

-- Reads the events pi appended since the last poll.
function Channel:poll()
	local raw = fs.read(self:path("head.json"))
	-- No log when ttt starts: whatever comes later is new, not history.
	if not raw then
		if self.gen == nil then self.gen = "" end
		return
	end
	local head = json.decode(raw)
	if not head or not head.gen then return end
	if head.gen ~= self.gen then
		-- The first log seen is history from before ttt started: skip it.
		self.offset = self.gen == nil and head.size or 0
		self.gen = head.gen
	end
	if head.size <= self.offset then return end
	local log = fs.read(self:path("events.jsonl"))
	if not log then return end
	local chunk = log:sub(self.offset + 1)
	for line in util.lines(chunk) do
		self.offset = self.offset + #line
		local ok, ev = pcall(json.decode, line)
		local h = ok and type(ev) == "table" and self.handlers[ev.op]
		if h then
			local fine, err = pcall(h.fn, ev)
			if not fine then self.log("error", "symbiosis " .. ev.op .. ": " .. tostring(err)) end
		end
	end
end

return M
end
modules["core.settings"] = function(...)
-- Settings: each one a list of values; the features define them, the panel
-- (ctrl+k h) shows them, settings.json keeps them.
--
--   settings:define("speed", {
--     values = { 10, 20, 0 },  -- the values, in the order Enter cycles them
--     default = 2,             -- the index before you choose one
--     label = "Replay speed",  -- in the panel; nil: not in the panel
--     order = 10,              -- the place in the panel
--     text = function(v) ... end, -- the value as the panel shows it
--     steps = true,            -- "-" and "=" in the panel step it (no wrap)
--     persist = false,         -- not kept in settings.json (default: kept)
--     on_change = function(v) ... end,
--   })
local fs = require("ttt.fs")
local json = require("ttt.json")

local Settings = {}
Settings.__index = Settings

local M = {}

function M.new(path, owner)
	return setmetatable({ path = path, defs = {}, list = {}, saved = {}, owner = owner or function() return nil end }, Settings)
end

function Settings:define(key, def)
	if self.defs[key] then error("setting " .. key .. " is defined twice", 2) end
	if type(def.values) ~= "table" or #def.values == 0 then error("setting " .. key .. " has no values", 2) end
	def.key = key
	def.index = def.default or 1
	def.order = def.order or 50
	def.owner = self.owner()
	def.seq = #self.list + 1
	self.defs[key] = def
	table.insert(self.list, def)
	return def
end

-- Drops the settings a feature defined (its setup failed).
function Settings:drop(owner)
	local keep = {}
	for _, def in ipairs(self.list) do
		if def.owner == owner then self.defs[def.key] = nil else table.insert(keep, def) end
	end
	self.list = keep
end

function Settings:get(key)
	local def = self.defs[key]
	return def.values[def.index]
end

function Settings:index(key) return self.defs[key].index end

function Settings:text(key)
	local def = self.defs[key]
	local v = def.values[def.index]
	return def.text and def.text(v) or tostring(v)
end

function Settings:set_index(key, i)
	local def = self.defs[key]
	def.index = i
	-- A file that cannot be written does not stop the change.
	if def.persist ~= false then pcall(self.save, self) end
	if def.on_change then def.on_change(def.values[i]) end
end

-- One step up or down, not past the ends.
function Settings:step(key, delta)
	local def = self.defs[key]
	self:set_index(key, math.max(1, math.min(#def.values, def.index + delta)))
end

-- The next value, round.
function Settings:cycle(key)
	local def = self.defs[key]
	self:set_index(key, def.index % #def.values + 1)
end

-- The definitions with a label, in panel order.
function Settings:shown()
	local out = {}
	for _, def in ipairs(self.list) do
		if def.label then table.insert(out, def) end
	end
	table.sort(out, function(a, b)
		if a.order ~= b.order then return a.order < b.order end
		return a.seq < b.seq
	end)
	return out
end

-- Reads settings.json: a value it names is chosen when it is one of the
-- setting's values. Keys no setting knows are kept as they are.
function Settings:load()
	local ok, saved = pcall(json.decode, fs.read(self.path) or "")
	if not ok or type(saved) ~= "table" then return end
	self.saved = {}
	for k, v in pairs(saved) do
		if type(k) == "string" then self.saved[k] = v end
	end
	for _, def in ipairs(self.list) do
		if def.persist ~= false then
			for i, v in ipairs(def.values) do
				if v == saved[def.key] then def.index = i end
			end
		end
	end
end

function Settings:save()
	local out = {}
	for k, v in pairs(self.saved) do out[k] = v end
	for _, def in ipairs(self.list) do
		if def.persist ~= false then out[def.key] = def.values[def.index] end
	end
	fs.write(self.path, json.encode(out))
end

return M
end
modules["core.util"] = function(...)
-- Pure helpers for text, positions and paths. No ttt API here: the Lua unit
-- tests (test/lua) load this module as it is.
local M = {}

-- Each line of `text` that ends in "\n", with its "\n". Not gmatch("[^\n]*\n"):
-- in ttt 1.7.1 that crashes (nil pointer) on text with an empty line.
function M.lines(text)
	local i = 1
	return function()
		local j = text:find("\n", i, true)
		if not j then return nil end
		local line = text:sub(i, j)
		i = j + 1
		return line
	end
end

-- Characters (not bytes) in a UTF-8 string: editor columns count characters.
function M.runes(s)
	local _, continuation = s:gsub("[\128-\191]", "")
	return #s - continuation
end

-- The position just after `text`, written from (line, col).
function M.after(line, col, text)
	local newlines = select(2, text:gsub("\n", ""))
	if newlines == 0 then return line, col + M.runes(text) end
	local tail = text:match("[^\n]*$")
	return line + newlines, 1 + M.runes(tail)
end

-- The position of byte `b` (1-based) in `text`.
function M.position(text, b)
	return M.after(1, 1, text:sub(1, b - 1))
end

-- The common prefix of two strings, in bytes, not ending inside a character.
function M.prefix(a, b)
	local n = math.min(#a, #b)
	local i = 0
	while i < n and a:byte(i + 1) == b:byte(i + 1) do i = i + 1 end
	while i > 0 and i < #b and b:byte(i + 1) >= 128 and b:byte(i + 1) < 192 do i = i - 1 end
	return i
end

-- The bytes of the first `n` characters of `s`.
function M.rune_bytes(s, n)
	local i, count = 1, 0
	while i <= #s and count < n do
		local b = s:byte(i)
		i = i + (b >= 240 and 4 or b >= 224 and 3 or b >= 192 and 2 or 1)
		count = count + 1
	end
	return math.min(i - 1, #s)
end

function M.adler32(s)
	local a, b = 1, 0
	for i = 1, #s do
		a = (a + s:byte(i)) % 65521
		b = (b + a) % 65521
	end
	return b * 65536 + a
end

-- The first `n` characters of `s`, with "…" when cut.
function M.cut(s, n)
	if M.runes(s) <= n then return s end
	local out, count = {}, 0
	for ch in s:gmatch("[^\128-\191][\128-\191]*") do
		if count == n - 1 then break end
		table.insert(out, ch)
		count = count + 1
	end
	return table.concat(out) .. "…"
end

-- Lines for open_diff; a final "\n" does not make an empty last line.
function M.split(text)
	local out = {}
	if type(text) ~= "string" then return out end
	local i = 1
	while i <= #text do
		local j = text:find("\n", i, true)
		if not j then
			table.insert(out, text:sub(i))
			break
		end
		table.insert(out, text:sub(i, j - 1))
		i = j + 1
	end
	return out
end

function M.starts_with(s, p) return s:sub(1, #p) == p end

-- Paths ---------------------------------------------------------------------

function M.name(path) return path:match("[^/]+$") or path end

function M.parent(path)
	return path:match("^(.*)/[^/]*$") or path
end

-- "~" for the home folder (Linux, macOS).
function M.short(path)
	return (path:gsub("^/home/[^/]+", "~"):gsub("^/Users/[^/]+", "~"))
end

function M.split_path(rel)
	local parts = {}
	for part in rel:gmatch("[^/]+") do table.insert(parts, part) end
	return parts
end

-- Keys ----------------------------------------------------------------------

-- A key that changes the text: a character, or Enter, Tab, Backspace, Delete.
-- Not a move, and not a key with ctrl or alt.
function M.edits_text(key)
	if key.mod and key.mod ~= "" and key.mod ~= "shift" then return false end
	if key.rune and key.rune ~= "" then return true end
	local k = tostring(key.key or ""):lower()
	return k == "enter" or k == "tab" or k == "backspace" or k == "delete"
end

-- ctrl+v, ctrl+x, ctrl+z, ctrl+y, ctrl+s: they change or save the buffer.
local CHANGES_KEYS = { v = true, x = true, z = true, y = true, s = true }

function M.changes_buffer(key)
	if M.edits_text(key) then return true end
	local k = tostring(key.key or key.rune or ""):lower():match("(%a)$")
	return key.mod == "ctrl" and k ~= nil and CHANGES_KEYS[k] == true
end

-- The lower-case name of a key: "esc", "enter", "a".
function M.key_name(key)
	return tostring(key.key or ""):lower()
end

return M
end
modules["features.autosave"] = function(...)
-- Autosave: a while after your last key press, the file is saved, so the
-- buffer is clean when pi writes it (a dirty buffer gets no preview and no
-- reload). Never while pi has a change to this file under way: that would
-- save a preview, or the old text over pi's write.
local ttt = require("ttt")
local editor = require("ttt.editor")
local util = require("core.util")

-- Milliseconds after your last key press; 0 = off.
local AUTOSAVES = { 0, 1000, 3000 }

return {
	name = "autosave",
	needs = { "replay" },
	setup = function(app)
		local replay = app:need("replay")
		local settings = app.settings
		local timer = nil

		settings:define("autosave", {
			values = AUTOSAVES, default = 2, label = "Autosave", order = 30,
			text = function(ms) return ms == 0 and "off" or string.format("%g s after you type", ms / 1000) end,
		})

		-- `soon`: at once (a helpi! answer is complete: pi may go to another file next).
		local function schedule(soon)
			local ms = settings:get("autosave")
			local path = editor.file_path() or ""
			if ms == 0 or path == "" then return end
			if timer then ttt.clear_timeout(timer) end
			timer = ttt.set_timeout(soon and 10 or ms, function()
				timer = nil
				if editor.file_path() ~= path or not replay.quiet(path) then return end
				ttt.exec_command("file.save")
			end)
		end

		-- Late: only a key that no other feature took.
		app:on("key", function(key)
			if util.edits_text(key) then schedule() end
			return false
		end, 90)

		return { schedule = schedule }
	end,
}
end
modules["features.changes"] = function(...)
-- The diff key. pi/changes.ts keeps, per file, the text before pi's last
-- turn first changed it and the text after (changes/index.json and
-- changes/<key>.json). ctrl+k w shows that diff for the open file, or for
-- the last file pi changed.
local ttt = require("ttt")
local editor = require("ttt.editor")
local util = require("core.util")

local name = util.name

return {
	name = "changes",
	setup = function(app)
		local channel = app.channel

		local function show_changes()
			local index = channel:read_json("changes/index.json")
			if type(index) ~= "table" or type(index.files) ~= "table" or #index.files == 0 then
				return ttt.notify("symbiosis: pi changed no file in its last turn", "info")
			end
			local open = editor.file_path()
			local pick = index.files[#index.files]
			for _, f in ipairs(index.files) do
				if f.path == open then pick = f end
			end
			local change = channel:read_json("changes/" .. pick.key .. ".json")
			if type(change) ~= "table" then
				return ttt.notify("symbiosis: the changes to " .. name(pick.path) .. " are not readable", "warning")
			end
			if change.before == change.after then
				return ttt.notify("symbiosis: " .. name(pick.path) .. " is the same as before pi's last turn", "info")
			end
			ttt.open_diff("pi: " .. name(pick.path) .. " (last turn)", util.split(change.before), util.split(change.after), pick.path)
			if open and open ~= "" and pick.path ~= open then
				ttt.notify("symbiosis: pi did not change this file; this is " .. name(pick.path) .. ", its last change", "info")
			end
		end

		app:command({ id = "symbiosis.showChanges", title = "symbiosis: What pi Changed in Its Last Turn (diff)", key = "ctrl+k w", run = show_changes })
		app:hint({ key = "ctrl+k w", text = "what pi changed (diff)", order = 80 })

		return { show = show_changes }
	end,
}
end
modules["features.helpi"] = function(...)
-- helpi!: a comment that ends in `helpi!` asks the session the editor
-- follows, at once: 600 ms after your last change, or on Enter at the end of
-- its line. help.json carries the question and the code around it, as in
-- the buffer. pi asks its model in a side call (core/help.ts) and sends events
-- back:
--   help        pi has the question; it is thinking
--   help_start  the kind: note, code or ask; for code, the imports it needs
--   help_text   the answer so far (all of it)
--   help_done   the answer is complete, stopped, or failed
-- note: comment lines under the question, the first one starts "pi:". code:
-- takes the place of the comment, and missing imports go in at the top. ask:
-- the question went to pi's agent. All in one undo group: one ctrl+z takes
-- it back. While the answer is written, your typing in that file waits, and
-- the replay too. Esc stops it; what is written stays. Until the answer
-- starts, a line under the question shows that pi thinks (a spinner); it is
-- in the same undo group, and the answer takes its place.
--
-- The help events skip the replay's queue: they apply at once, and only for
-- the question under way.
local ttt = require("ttt")
local editor = require("ttt.editor")
local util = require("core.util")
local buffer = require("core.buffer")

local runes = util.runes

local OPENERS = { "<!--", "/*", "//", "--", "#", ";" }
local CLOSERS = { ["<!--"] = " -->", ["/*"] = " */" }
local HELP_MS = 600
local MAX_LINES = 150 -- a longer file sends its top and the lines around the question
local FRAMES = { "⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏" }

-- The comment on `line` when it ends in helpi!: where its opener is, and the indent.
local function helpi(line)
	local body = line:gsub("%s*%*/%s*$", ""):gsub("%s*%-%->%s*$", "")
	if not body:match("helpi!%s*$") then return nil end
	local best = nil
	for _, o in ipairs(OPENERS) do
		local b = body:find(o, 1, true)
		if b and b < #body - 5 then best = { byte = b, opener = o } break end
	end
	if not best then return nil end
	best.col = runes(line:sub(1, best.byte - 1)) + 1
	best.indent = line:match("^%s*")
	return best
end

-- The line without its last `helpi!` (and the space before it).
local function unmark(line)
	local at = line:match(".*()helpi!")
	if not at then return line end
	return line:sub(1, at - 1):gsub("%s+$", "") .. line:sub(at + 6)
end

-- The text the answer region holds for `body`. h: {kind, indent, opener}.
local function render(h, body, final)
	local out = {}
	local parts = util.split(body)
	if h.kind == "code" then
		for i, l in ipairs(parts) do
			if i == 1 then table.insert(out, l)
			else table.insert(out, "\n" .. (l == "" and "" or h.indent .. l)) end
		end
		return table.concat(out)
	end
	-- A note: one comment line each. A closer (*/, -->) only on a complete line.
	local closer = CLOSERS[h.opener] or ""
	if #parts == 0 then parts = { "" } end
	for i, l in ipairs(parts) do
		local text = (i == 1 and "pi: " or "") .. l
		local close = (final or i < #parts) and closer or ""
		table.insert(out, "\n" .. h.indent .. h.opener .. (text == "" and "" or " " .. text) .. close)
	end
	return table.concat(out)
end

-- After the last import line near the top (or after a package line), or at line 1.
local IMPORT_LINE = { "^import[%s{\"']", "^from%s", "^use%s", "^#include", "^require[%s(]", "^const%s.-=%s*require%(", "^using%s" }
local function import_at(all)
	local at, package = 0, 0
	for i = 1, math.min(#all, 200) do
		local l = all[i]
		for _, p in ipairs(IMPORT_LINE) do
			if l:match(p) then at = i break end
		end
		if l:match("^package%s") then package = i end
	end
	return at, package
end

local function setup(app)
	local replay = app:need("replay")
	local sessions = app:need("sessions")
	local channel = app.channel
	local help = nil       -- the question under way
	local seq = 0
	local timer = nil      -- asks after the pause
	local wait = nil       -- the timer that says pi did not take the question
	local asked = {}       -- path:line:text -> true: the pause does not ask again (Enter does)
	local quiet = 0        -- poll tick: changes before it are the plugin's own (the waiting line)

	local function show(text) replay.show(text) end

	-- The waiting line: a comment under the question, with the question's indent.
	local function loader_text(h)
		return h.indent .. h.opener .. " pi " .. FRAMES[h.frame] .. " thinking · Esc stops" .. (CLOSERS[h.opener] or "")
	end

	-- The line the waiting line is on now, if it is still there.
	local function loader_at(h)
		if not h.loader or editor.file_path() ~= h.path then return nil end
		if editor.get_line(h.loader) == h.loader_shown then return h.loader end
		for i, l in ipairs(editor.buffer_lines()) do
			if l == h.loader_shown then return i end
		end
		return nil
	end

	-- Shows the waiting line and opens the answer's undo group (the line is in it).
	local function show_loader()
		local h = help
		if not h or h.kind or h.group or editor.file_path() ~= h.path then return end
		if editor.get_line(h.line) ~= h.text then return end
		local cur = editor.cursor()
		editor.begin_undo_group()
		h.group = true
		h.frame = 1
		h.loader_shown = loader_text(h)
		buffer.editing = true
		if h.line < editor.line_count() then
			editor.insert(h.line + 1, 1, h.loader_shown .. "\n")
		else
			editor.insert(h.line, runes(h.text) + 1, "\n" .. h.loader_shown)
		end
		buffer.editing = false
		h.loader = h.line + 1
		editor.set_cursor(cur.line > h.line and cur.line + 1 or cur.line, cur.col)
	end

	-- The spinner turns: called on each poll tick.
	local function spin_loader()
		local h = help
		if not h or not h.loader or h.kind or app.ticks % 3 ~= 0 then return end
		local at = loader_at(h)
		if not at then return end
		local cur = editor.cursor()
		h.frame = h.frame % #FRAMES + 1
		h.loader_shown = loader_text(h)
		buffer.editing = true
		editor.set_line(at, h.loader_shown)
		buffer.editing = false
		h.loader = at
		editor.set_cursor(cur.line, cur.col)
	end

	-- Takes the waiting line away; the cursor stays where it was in your text.
	local function hide_loader(h)
		local at = loader_at(h)
		h.loader = nil
		if not at then return end
		local cur = editor.cursor()
		buffer.editing = true
		if at < editor.line_count() then
			editor.replace(at, 1, at + 1, 1, "")
		else
			local prev = editor.get_line(at - 1) or ""
			editor.replace(at - 1, runes(prev) + 1, at, runes(h.loader_shown) + 1, "")
		end
		buffer.editing = false
		if cur.line > at then editor.set_cursor(cur.line - 1, cur.col)
		elseif cur.line == at then editor.set_cursor(at - 1, runes(editor.get_line(at - 1) or "") + 1)
		else editor.set_cursor(cur.line, cur.col) end
	end

	local function help_end(message, level)
		local h = help
		if not h then return end
		help = nil
		if wait then ttt.clear_timeout(wait) wait = nil end
		if h.loader then hide_loader(h) end
		quiet = app.ticks + 8
		if h.group then
			editor.end_undo_group()
			-- Only the waiting line was in the group (Esc or an error before the
			-- answer): undo it, so your next ctrl+z is not a step that does nothing.
			if not h.region then
				local cur = editor.cursor()
				buffer.editing = true
				ttt.exec_command("editor.undo")
				buffer.editing = false
				editor.set_cursor(cur.line, cur.col)
			end
		end
		if message then ttt.notify("symbiosis: " .. message, level or "info") end
		show()
		local autosave = app:get("autosave")
		if h.region and autosave then autosave.schedule(true) end
	end

	local function help_write(fields)
		channel:write_json("help.json", fields)
	end

	-- `again`: Enter asks also a line that was asked before (after ctrl+z, say).
	local function ask_help(again)
		if not app.loaded or help or buffer.editing or replay.running() then return end
		local path = editor.file_path()
		if not path or path == "" then return end
		local pos = editor.cursor()
		local text = editor.get_line(pos.line) or ""
		local c = helpi(text)
		if not c then return end
		local key = path .. ":" .. pos.line .. ":" .. text
		if asked[key] and not again then return end
		asked[key] = true
		sessions.refresh()
		local owner = sessions.owner()
		if not owner then return ttt.notify("symbiosis: helpi! needs a pi session; none runs", "warning") end
		if owner.version ~= sessions.PROTOCOL then
			return ttt.notify("symbiosis: pi " .. owner.name .. " runs an old symbiosis: /reload it", "warning")
		end
		local all = editor.buffer_lines()
		local first, last, head = 1, #all, ""
		if #all > MAX_LINES then
			first, last = math.max(1, pos.line - 40), math.min(#all, pos.line + 20)
			if first > 21 then head = table.concat(all, "\n", 1, 20) else first = 1 end
		end
		seq = seq + 1
		help = {
			id = os.time() .. "-" .. seq, path = path, line = pos.line, text = text,
			byte = c.byte, col = c.col, opener = c.opener, indent = c.indent, to = owner.id, name = owner.name,
		}
		help_write({
			id = help.id, to = help.to, path = path, line = pos.line, question = text,
			language = editor.language() or "", head = head,
			window = { first = first, text = table.concat(all, "\n", first, last) }, cancel = false,
		})
		show("helpi! → " .. owner.name)
		-- After the key that asked (Enter goes in first).
		ttt.set_timeout(10, function()
			local fine, err = pcall(show_loader)
			if not fine then
				buffer.editing = false
				app.log("error", "symbiosis helpi! loader: " .. tostring(err))
			end
		end)
		wait = ttt.set_timeout(3000, function()
			wait = nil
			if help and not help.taken then
				asked[key] = nil
				help_end("pi " .. help.name .. " did not take the question: /reload it?", "error")
			end
		end)
	end

	local function help_soon()
		if not app.loaded or buffer.editing or help or app.ticks < quiet then return end
		if timer then ttt.clear_timeout(timer) end
		timer = ttt.set_timeout(HELP_MS, function()
			timer = nil
			local fine, err = pcall(ask_help)
			if not fine then app.log("error", "symbiosis helpi!: " .. tostring(err)) end
		end)
	end

	-- Esc: pi stops the side call; what is written stays.
	local function help_stop()
		if not help then return end
		help_write({ id = help.id, to = help.to, cancel = true })
		help.stopped = true
		help_end(help.region and "helpi! stopped" or "helpi! stopped before pi answered")
	end

	-- Missing imports go in at the top. Returns how many lines went in.
	local function add_imports(imports, before)
		local all = editor.buffer_lines()
		local have = {}
		for _, l in ipairs(all) do have[l:match("^%s*(.-)%s*$")] = true end
		local new = {}
		for _, imp in ipairs(imports or {}) do
			local t = imp:match("^%s*(.-)%s*$")
			if t ~= "" and not have[t] then table.insert(new, t) have[t] = true end
		end
		if #new == 0 then return 0 end
		local at, package = import_at(all)
		local text = table.concat(new, "\n") .. "\n"
		local line = at + 1
		if at == 0 then
			-- No imports yet: after a package line, or at the top; then a blank line.
			line = package > 0 and package + 1 or 1
			if package > 0 then text = "\n" .. text end
			if (all[line] or "") ~= "" then text = text .. "\n" end
		end
		if line > #all then
			editor.insert(#all, runes(all[#all] or "") + 1, "\n" .. text:sub(1, -2))
		else
			editor.insert(line, 1, text)
		end
		if line > before then return 0 end
		return select(2, text:gsub("\n", ""))
	end

	local function help_taken()
		help.taken = true
		if wait then ttt.clear_timeout(wait) wait = nil end
		show("helpi! · " .. help.name .. " thinks · Esc stops")
	end

	local function help_start(ev)
		help.kind = ev.kind
		if replay.running() then replay.finish() end
		if not buffer.on_buffer(help.path) then return help_end("helpi!: the file did not open", "warning") end
		-- The question may have moved: find its line again.
		local line = help.line
		if editor.get_line(line) ~= help.text then
			line = nil
			for i, l in ipairs(editor.buffer_lines()) do
				if l == help.text then line = i break end
			end
			if not line then return help_end("helpi!: the question changed; the answer is not written", "warning") end
		end
		-- The waiting line goes; the answer takes its place.
		if help.loader then hide_loader(help) end
		-- You pressed Enter after the question: the cursor stays on your new line.
		local cursor = editor.cursor()
		if cursor.line > line then help.below = { lines = cursor.line - line, col = cursor.col } end
		if not help.group then
			editor.begin_undo_group()
			help.group = true
		end
		buffer.editing = true
		if ev.kind == "code" then
			line = line + add_imports(ev.imports, line)
			help.region = { line = line, col = help.col, text = help.text:sub(help.byte) }
		else
			local stripped = unmark(help.text)
			editor.set_line(line, stripped)
			help.region = { line = line, col = runes(stripped) + 1, text = "" }
		end
		buffer.editing = false
		if ev.kind == "ask" then
			buffer.set_region(help.region, render(help, "asked " .. help.name .. "; its answer comes in pi", true), help.below)
			return help_end()
		end
		show("helpi! · " .. help.name .. " writes · Esc stops")
	end

	local function help_text(ev)
		if help.region then buffer.set_region(help.region, render(help, ev.text or "", false), help.below) end
	end

	local function help_done(ev)
		if ev.error then
			asked[help.path .. ":" .. help.line .. ":" .. help.text] = nil
			return help_end("helpi! failed: " .. tostring(ev.error), "error")
		end
		if help.region and not ev.stopped then buffer.set_region(help.region, render(help, ev.text or "", true), help.below) end
		help_end()
	end

	local handlers = { help = help_taken, help_start = help_start, help_text = help_text, help_done = help_done }

	-- A help event, at once (not through the replay queue): only for the question under way.
	local function apply_help(ev)
		if not help or help.stopped or ev.id ~= help.id then return end
		if ev.op ~= "help" and not help.taken then help_taken(ev) end
		local fine, err = pcall(handlers[ev.op], ev)
		if not fine then
			buffer.editing = false
			app.log("error", "symbiosis " .. ev.op .. ": " .. tostring(err))
			help_end("helpi! failed in the editor: " .. tostring(err), "error")
		end
	end
	for op in pairs(handlers) do channel:on(op, apply_help) end

	-- While an answer is written, the replay waits, and your typing in its file too.
	replay.hold(function() return help ~= nil and help.group == true end)
	replay.lock(function(path) return help ~= nil and help.group == true and path == help.path end)

	-- Early: Esc stops an answer; Enter at the end of a helpi! line asks at
	-- once (the Enter still goes in).
	app:on("key", function(key)
		local k = tostring(key.key or ""):lower()
		if help and (k == "esc" or k == "escape") then
			help_stop()
			return true
		end
		if k == "enter" and (not key.mod or key.mod == "") and not help then
			local line = editor.current_line() or ""
			if editor.cursor().col > runes(line) and helpi(line) then
				if timer then ttt.clear_timeout(timer) timer = nil end
				local fine, err = pcall(ask_help, true)
				if not fine then app.log("error", "symbiosis helpi!: " .. tostring(err)) end
			end
		end
		return false
	end, 10)

	app:on("change", help_soon)
	app:on("tick", spin_loader, 60)
	app:hint({ key = "// … helpi!", text = "ask pi here: wait, or Enter", order = 90 })
	app:hint({ key = "Esc", text = "stop a helpi! answer", order = 100 })

	return {
		busy = function() return help ~= nil end,
		stop = help_stop,
	}
end

return {
	name = "helpi",
	needs = { "replay", "sessions" },
	setup = setup,
	-- For the tests.
	helpi = helpi,
	unmark = unmark,
	render = render,
	import_at = import_at,
}
end
modules["features.marks"] = function(...)
-- The gutter: ▌ on each line pi typed in this change (the call shown now),
-- π on the line it types now. Gutter marks are ttt's bookmarks, one per line,
-- shared with other plugins: a line with another plugin's mark keeps it. They
-- stay at their line numbers when the text moves, so they are drawn again on
-- each tick, after the replay's (only when something changed). They go when
-- the change is all shown. Needs the editor.bookmarks permission.
local ttt = require("ttt")
local editor = require("ttt.editor")

local BAR, NOW = "▌", "π"

return {
	name = "marks",
	needs = { "replay" },
	setup = function(app)
		local replay = app:need("replay")
		local has_marks, bookmarks = pcall(require, "ttt.bookmarks")
		local marked, marked_path, marks_key = {}, nil, ""

		local function ours(line)
			local b = bookmarks.get(line)
			return b and (b.icon == BAR or b.icon == NOW)
		end

		local function draw()
			local path = editor.file_path()
			if path ~= marked_path then marked, marked_path, marks_key = {}, path, "" end
			local want, now = {}, nil
			local t = replay.typing()
			if t and t.path == path then
				local last = editor.line_count()
				for _, r in ipairs(t.regions) do
					if r.text ~= "" then
						local n = select(2, r.text:gsub("\n", ""))
						if n > 0 and r.text:sub(-1) == "\n" then n = n - 1 end
						for l = r.line, math.min(r.line + n, last) do want[l] = BAR end
					end
				end
				if t.at and t.at <= last then
					now = t.at
					want[now] = NOW
				end
			end
			local parts = {}
			for l, icon in pairs(want) do table.insert(parts, l .. icon) end
			table.sort(parts)
			local key = table.concat(parts, ",")
			-- Another plugin may have replaced every mark (on opening a file).
			if key == marks_key and not (now and not ours(now)) then return end
			marks_key = key
			for l in pairs(marked) do
				if not want[l] and ours(l) then bookmarks.remove(l) end
			end
			marked = {}
			for l, icon in pairs(want) do
				local b = bookmarks.get(l)
				if not b or b.icon == BAR or b.icon == NOW then
					if not b or b.icon ~= icon then bookmarks.set(l, icon, "success") end
					marked[l] = true
				end
			end
		end

		app:on("tick", function()
			if not has_marks then return end
			local fine, err = pcall(draw)
			if not fine then
				has_marks = false
				app.log("error", "symbiosis gutter marks: " .. tostring(err))
			end
		end, 60)
	end,
}
end
modules["features.panel"] = function(...)
-- The panel: ctrl+k h. The settings that features define (Enter cycles a
-- value; "-" and "=" step one that steps), the sections features add (the pi
-- sessions, ...), every key hint, and the notes. ttt calls render on every
-- frame: no file reads here. Up/Down move in a list, Tab to the next list,
-- Esc closes.
local ttt = require("ttt")

-- Settings labels are padded to this many characters, so the values line up.
local LABEL_WIDTH = 16

return {
	name = "panel",
	setup = function(app)
		local settings = app.settings

		local function render(panel)
			panel:title("symbiosis")
			local shown = settings:shown()
			if #shown > 0 then
				panel:label({ text = "Settings · Enter changes", style = "bold" })
				local items = {}
				for _, def in ipairs(shown) do
					local label = def.label
					if #label < LABEL_WIDTH then label = label .. string.rep(" ", LABEL_WIDTH - #label) else label = label .. " " end
					table.insert(items, { id = def.key, label = label .. settings:text(def.key) })
				end
				panel:list({
					items = items,
					key_commands = { ["-"] = "slower", ["="] = "faster" },
					on_command = function(command, node)
						local def = settings.defs[node.id]
						if not def then return end
						if def.steps and command == "slower" then settings:step(def.key, -1)
						elseif def.steps and command == "faster" then settings:step(def.key, 1)
						elseif command == "activate" or def.steps then
							settings:cycle(def.key)
						end
					end,
				})
			end
			for _, s in ipairs(app.sections) do
				local ok, err = pcall(s.render, panel)
				if not ok then app.log("error", "symbiosis " .. tostring(s.owner) .. " panel: " .. tostring(err)) end
			end
			if #app.hints > 0 then
				panel:label({ text = "Keys", style = "bold", margin_top = 1 })
				local keys = {}
				for _, h in ipairs(app.hints) do table.insert(keys, { key = h.key, value = h.value }) end
				panel:keyvalue(keys)
			end
			for i, n in ipairs(app.notes) do
				panel:label({ text = n.text, style = "muted", margin_top = i == 1 and 1 or nil })
			end
		end

		local function open()
			ttt.open_drawer({ width = 52, min_width = 36, side = "right", render = render })
		end

		app:command({ id = "symbiosis.help", title = "symbiosis: Settings, Sessions and Keys", key = "ctrl+k h", run = open })
		app:hint({ key = "ctrl+k h", text = "this panel", order = 10 })
		app:note("Esc closes · clicks: π goes to pi, ▶ speed cycles", 90)

		return { open = open, render = render }
	end,
}
end
modules["features.plan"] = function(...)
-- The timeline: pi's plan (the `plan` tool, pi/plan.ts) comes in the owner's
-- session record. The status bar shows it as "✓ 3 › ▶ now › next"; ctrl+k v
-- (or a click) shows the whole plan in a drawer.
local ttt = require("ttt")
local json = require("ttt.json")
local util = require("core.util")

local PLAN_WIDTH = 56 -- the timeline in the status bar, in characters

local function plan_of(rec)
	return rec and type(rec.plan) == "table" and rec.plan or {}
end

-- One line: "✓ 3 › ▶ now › next › next +2". Done steps are a count; "next"
-- steps drop off at the right when the line is full.
local function plan_line(steps)
	if #steps == 0 then return nil end
	local done, now, nexts = 0, nil, {}
	for _, s in ipairs(steps) do
		if s.state == "done" then done = done + 1
		elseif s.state == "now" and not now then now = s.text
		else table.insert(nexts, s.text) end
	end
	if not now and #nexts == 0 then return "✓ " .. done .. " done" end
	local line = done > 0 and ("✓ " .. done) or ""
	local function add(part)
		line = line == "" and part or (line .. " › " .. part)
	end
	if now then add("▶ " .. util.cut(now, 28)) end
	local shown = 0
	for i, text in ipairs(nexts) do
		local part = util.cut(text, 20)
		local rest = #nexts - i
		local room = PLAN_WIDTH - util.runes(line) - 3 - (rest > 0 and 3 or 0)
		if shown > 0 and util.runes(part) > room then break end
		add(part)
		shown = shown + 1
	end
	if shown < #nexts then line = line .. " +" .. (#nexts - shown) end
	return line
end

return {
	name = "plan",
	needs = { "sessions" },
	plan_line = plan_line, -- for the unit tests
	setup = function(app)
		local sessions = app:need("sessions")
		local seen = nil   -- the plan as last shown, to redraw only on a change
		local drawer = nil -- the plan drawer's panel, once opened: redrawn on a change
		local open

		local function render(panel)
			drawer = panel
			local owner = sessions.owner()
			local steps = plan_of(owner)
			panel:title({ text = "pi plan", badge = owner and owner.name or "no session" })
			if #steps == 0 then
				panel:label({ text = "No plan yet. pi sends one for a task with several steps.", style = "muted" })
			end
			for _, s in ipairs(steps) do
				if s.state == "done" then
					panel:label({ text = "✓ " .. s.text, style = "muted" })
				elseif s.state == "now" then
					panel:label({ text = "▶ " .. s.text, style = "bold" })
				else
					panel:label({ text = "· " .. s.text })
				end
			end
			panel:label({ text = "Esc closes", style = "muted", margin_top = 1 })
		end

		-- Shows the owner's plan; only when it changed, so the drawer does not flicker.
		local function show()
			local owner = sessions.owner()
			local steps = plan_of(owner)
			local now = (owner and owner.id or "") .. json.encode(steps)
			if now == seen then return end
			seen = now
			local line = plan_line(steps)
			if line then
				ttt.set_status_item("left", "symbiosis.plan", line, { priority = 950, on_click = function() open() end })
			else
				ttt.remove_status_item("symbiosis.plan")
			end
			if drawer then drawer:redraw() end
		end

		-- ctrl+k v, or a click on the timeline: the whole plan in a drawer. The
		-- drawer takes the keys while it is open, so Esc closes it (as every ttt
		-- drawer); a plugin key cannot reach it, and the editor cannot keep the focus.
		open = function()
			ttt.open_drawer({ width = 48, min_width = 30, side = "right", render = render })
		end

		app:on("sessions", show)
		app:command({ id = "symbiosis.showPlan", title = "symbiosis: Show pi's Plan", key = "ctrl+k v", run = function() open() end })
		app:hint({ key = "ctrl+k v", text = "pi's plan", order = 70 })
		return { open = open, plan_of = plan_of }
	end,
}
end
modules["features.replay"] = function(...)
-- The replay. pi (the extension in pi/) appends events to events.jsonl; this
-- feature
--   * replays each write and edit in the buffer at the speed you set, as a
--     preview: one undo group for each run of changes to one file;
--   * writes ack.json when it has shown a change. pi does not wait for the
--     editor: it waits only when more changes than your limit (`lag`) are
--     not shown yet. So the file on disk is where pi is now, and the buffer
--     is the replay, behind it;
--   * at the end of a run: undoes the preview and opens the file again from
--     disk: the file on disk is always the truth;
--   * follows the result: opens the file at the changed line.
-- Rules: a buffer with unsaved changes is never touched; while a run is
-- replayed in a file, your typing there waits; pinned (ctrl+k a) means no
-- preview and no jumps, but the end of the turn (a stop) moves the editor
-- anyway. See docs/design.md.
--
-- Hooks it emits: "follow" (path) when the editor followed pi into a file.
-- replay.typing() is the change typed now, for the gutter (features/marks.lua).
-- Other features may hold the replay (replay.hold) or lock a file against
-- your typing (replay.lock).
local ttt = require("ttt")
local editor = require("ttt.editor")
local util = require("core.util")
local buffer = require("core.buffer")
local POLL_MS = require("core.app").POLL_MS

-- Typing speeds of the preview, in characters per second; 0 = as fast as pi sends.
local SPEEDS = { 10, 20, 40, 80, 160, 320, 640, 1280, 0 }
-- How many changes pi may make that the editor has not shown yet; -1 = no limit.
-- 0 = pi waits for each change, as it did before.
local LAGS = { 0, 3, 10, -1 }

local name = util.name

return {
	name = "replay",
	setup = function(app)
		local settings, channel = app.settings, app.channel
		local calls = {}       -- call id -> call
		local run = nil        -- {path, line, calls, changed}: the file being replayed, one undo group
		local active = nil     -- the call the replay types now (in `run`)
		local disk = {}        -- path -> the sum of the file after pi's last change, as read
		local acks = {}        -- the last call ids acknowledged
		local here = nil       -- {path, line, mark}: what the status bar shows
		local paused = false   -- ctrl+k space: the replay stops; pi goes on up to the lag limit
		local behind = 0       -- the changes pi made that the replay has not shown yet
		local queue = {}       -- the events read from the log, not yet applied
		local qhead = 1
		local budget = 0       -- the characters the preview may type now
		local rush = nil       -- ctrl+k .: the call whose preview shows at once
		local held = nil       -- a timer: "your typing waits" stays in the bar for a while
		local holds = {}       -- fn() -> true: the replay waits (a helpi! answer is written)
		local locks = {}       -- fn(path) -> true: your typing in that file waits
		local show, finish

		local function pinned() return settings:get("pin") end

		local function follow(path) app:emit("follow", path) end

		-- Settings ---------------------------------------------------------------

		settings:define("speed", {
			values = SPEEDS, default = 5, label = "Replay speed", order = 10, steps = true,
			text = function(cps) return cps == 0 and "max" or string.format("%d/s", cps) end,
			on_change = function() show() end,
		})
		settings:define("lag", {
			values = LAGS, default = 2, label = "pi ahead (max)", order = 20,
			text = function(n)
				if n < 0 then return "no limit" end
				if n == 0 then return "0 (pi waits for each change)" end
				return string.format("%d changes", n)
			end,
			-- How far pi may run ahead of the replay. pi reads it from ttt.json.
			on_change = function() channel:heartbeat() end,
		})

		-- The view -----------------------------------------------------------------

		local function pace_text()
			local text = paused and "⏸ paused" or "▶ " .. settings:text("speed")
			if behind > 0 then text = text .. string.format(" · %d behind", behind) end
			return text
		end

		local function toggle_pin() settings:cycle("pin") end

		show = function(text)
			local mode = pinned() and "pinned" or "following"
			if held then mode = mode .. " · your typing waits" end
			ttt.set_status_item("left", "symbiosis.speed", pace_text(), { priority = 1001, on_click = function() settings:cycle("speed") end })
			if text then
				ttt.set_status_item("left", "symbiosis", "pi " .. text .. " · " .. mode, { on_click = toggle_pin })
			elseif here then
				ttt.set_status_item("left", "symbiosis", string.format("pi %s %s:%d · %s", here.mark, name(here.path), here.line, mode), { on_click = toggle_pin })
			else
				ttt.set_status_item("left", "symbiosis", "pi · " .. mode, { on_click = toggle_pin })
			end
		end

		local function go()
			if not here then return end
			ttt.open_file(here.path, here.line)
			follow(here.path)
		end

		settings:define("pin", {
			values = { false, true }, label = "Editor", order = 40, persist = false,
			text = function(v) return v and "pinned" or "follows pi" end,
			-- Pinning ends the replay; leaving the pin goes to where the agent is now.
			on_change = function(v)
				if v and run then finish() end
				if not v then go() end
				show()
			end,
		})

		-- Calls ---------------------------------------------------------------------
		-- A run: the changes that the replay shows in one file, one after the other,
		-- in one undo group. Each call types on top of the one before, so an edit
		-- finds its old text in the buffer as pi did on disk. The run ends when the
		-- replay goes to another file, at the end of the turn, or when it has shown
		-- all that pi sent: then `finish` undoes the group and opens the file again,
		-- which reloads it from disk.

		-- buffer.set_region, and: the other regions of the change below this one
		-- move with its line count; run.at is the line the cursor ends on.
		local function set_region(r, text)
			local d = select(2, text:gsub("\n", "")) - select(2, r.text:gsub("\n", ""))
			if d ~= 0 and active and active.regions then
				for _, o in ipairs(active.regions) do
					if o ~= r and o.line > r.line then o.line = o.line + d end
				end
			end
			buffer.set_region(r, text)
			if run then run.at = (util.after(r.line, r.col, text)) end
		end

		local function ack(id)
			table.insert(acks, id)
			while #acks > 200 do table.remove(acks, 1) end
			channel:write_json("ack.json", acks)
		end

		-- Ends the run: the preview is undone and the file comes from disk again.
		-- A buffer with unsaved changes does not reload when the file changes on
		-- disk, and after the undo it is clean but old: closing the tab and opening
		-- the file again reloads it. ttt's notice about the change on disk goes too.
		finish = function()
			local r = run
			if not r then return end
			run, active = nil, nil
			for id in pairs(r.calls) do
				local c = calls[id]
				if c then c.skip = c.skip or "ended" end
			end
			editor.end_undo_group()
			if not r.changed or not buffer.on_buffer(r.path) then return end
			buffer.editing = true
			ttt.exec_command("editor.undo")
			ttt.exec_command("tab.close")
			buffer.editing = false
			local line = here and here.path == r.path and here.line or r.line or 1
			ttt.open_file(r.path, line)
			ttt.notify("")
		end

		local function busy(path)
			return run ~= nil and run.path == path
		end

		local function start(ev)
			local c = { id = ev.call, tool = ev.tool, path = ev.path, edits = {}, values = {}, regions = {} }
			calls[ev.call] = c
			if pinned() then c.skip = "pinned" return end
			if run and run.path ~= ev.path then finish() end
			if run then
				-- The next change in the same file: it types on top of the one before.
				if not buffer.on_buffer(ev.path) then c.skip = "not opened" return end
			else
				ttt.open_file(ev.path)
				if editor.file_path() ~= ev.path then c.skip = "not opened" return end
				follow(ev.path)
				local text = editor.buffer_text()
				-- Clean: the buffer is the file as pi found it, or as pi last wrote it
				-- (a clean buffer reloads when pi is ahead of the replay).
				local sum = util.adler32(text)
				local clean = (ev.sum == nil and text == "") or sum == ev.sum or sum == disk[ev.path]
				if not clean then
					c.skip = "unsaved"
					ttt.notify("symbiosis: " .. name(ev.path) .. " has unsaved changes; no preview", "warning")
					return
				end
				editor.begin_undo_group()
				run = { path = ev.path, calls = {}, changed = false }
				-- pi may already have changed the file again: show the change from
				-- the text pi started from.
				local before = ev.before or (ev.sum == nil and "" or nil)
				if before and before ~= text then
					buffer.editing = true
					set_region(buffer.whole(), before)
					buffer.editing = false
					run.changed = true
				end
			end
			run.calls[c.id] = true
			active = c
			show("✎ writing " .. name(ev.path))
			if ev.tool == "write" then
				-- A full write clears the buffer and types the new text in.
				c.region = buffer.whole()
				if c.region.text ~= "" then set_region(c.region, "") run.changed = true end
				table.insert(c.regions, c.region)
			end
		end

		local function edit_text(c, i, part, value)
			local e = c.edits[i] or {}
			c.edits[i] = e
			if e.skip then return end
			if part == "old" then
				local text = editor.buffer_text()
				local b = text:find(value, 1, true)
				if value == "" or not b or text:find(value, b + 1, true) then e.skip = true return end
				local line, col = util.position(text, b)
				e.region = { line = line, col = col, text = value }
				local el, ec = util.after(line, col, value)
				editor.set_selection(line, col, el, ec)
				buffer.reveal(line)
				run.line, run.at = line, line
			elseif e.region then
				editor.clear_selection()
				if not e.marked then
					e.marked = true
					table.insert(c.regions, e.region)
				end
				set_region(e.region, value)
				run.changed = true
			end
		end

		-- Applies a text event to the value it names: its first `from` bytes, then `text`.
		local function grow(value, ev)
			return (value or ""):sub(1, ev.from) .. ev.text
		end

		local function text(ev)
			local c = calls[ev.call]
			if not c or c.skip then return end
			if not run or active ~= c or not buffer.on_buffer(c.path) then c.skip = "lost" return end
			local value = grow(c.values[ev.key], ev)
			c.values[ev.key] = value
			if ev.key == "content" then
				set_region(c.region, value)
				run.changed = true
				run.line = 1
			else
				local i, part = ev.key:match("^edits%.(%d+)%.(%a+)$")
				if i then edit_text(c, tonumber(i), part, value) end
			end
			local lines = select(2, value:gsub("\n", ""))
			show(string.format("✎ writing %s +%d lines", name(c.path), lines))
		end

		-- The call's text is all shown: acknowledge it. The run goes on.
		local function ready(ev)
			local c = calls[ev.call]
			if c then
				c.readied = true
				if active == c then active = nil end
				if editor.file_path() == c.path then editor.clear_selection() end
			end
			if rush == ev.call then rush = nil end
			ack(ev.call)
		end

		-- The call will not run: its preview must go, and it is mixed with the run's.
		local function abort(ev)
			local c = calls[ev.call]
			calls[ev.call] = nil
			if rush == ev.call then rush = nil end
			if c and run and run.calls[c.id] then pcall(finish) end
		end

		local function done(ev)
			calls[ev.call] = nil
			here = { path = ev.path, line = ev.line, mark = "✎" }
			if not ev.ok then return show() end
			-- In a run, the buffer is the replay: the jump waits for its end.
			if busy(ev.path) then run.line = ev.line return show() end
			if run then return show() end
			-- A new file shown before it existed reloads only when opened again.
			if not pinned() then
				ttt.open_file(ev.path, ev.line)
				follow(ev.path)
			end
			show()
		end

		local function stop(ev)
			if run then pcall(finish) end
			here = { path = ev.path, line = ev.line, mark = "■" }
			ttt.open_file(ev.path, ev.line)
			follow(ev.path)
			show()
		end

		-- True when the run has nothing left to type: every call in it was shown.
		local function run_done()
			if not run then return false end
			for id in pairs(run.calls) do
				local c = calls[id]
				if c and not c.readied then return false end
			end
			return true
		end

		local handlers = { start = start, text = text, ready = ready, abort = abort, done = done, stop = stop }

		-- The loop ------------------------------------------------------------------
		-- The channel hands the events to `read`, into the queue; pace() applies
		-- them. Text that the preview shows is typed at the speed you set: it costs
		-- characters from a budget that grows every tick. All other events cost
		-- nothing, but wait for the text before them. So `ready` comes after the
		-- last character, and pi, which waits for its ack, writes the file only
		-- when you have seen it all.

		local function read(ev)
			table.insert(queue, ev)
			-- pi changed the file now; the replay may be behind.
			if ev.op == "done" then
				disk[ev.path] = ev.sum
				-- ttt says the file changed on disk under the replay: not news here.
				if busy(ev.path) then
					for _, ms in ipairs({ 250, 700 }) do
						ttt.set_timeout(ms, function() if busy(ev.path) then ttt.notify("") end end)
					end
				end
			end
		end
		for op in pairs(handlers) do channel:on(op, read) end

		local function apply(ev)
			local fine, err = pcall(handlers[ev.op], ev)
			if not fine then app.log("error", "symbiosis " .. ev.op .. ": " .. tostring(err)) end
		end

		-- True when `ev` types text that the preview shows: a write's content or an
		-- edit's new text. An edit's old text is only selected.
		local function typed(ev)
			if ev.op ~= "text" or type(ev.text) ~= "string" then return false end
			local c = calls[ev.call]
			if not c or c.skip then return false end
			return ev.key == "content" or ev.key:match("%.new$") ~= nil
		end

		-- The changes pi made (it sent `ready`) that the replay has not shown yet.
		local function count_behind()
			local n = 0
			for i = qhead, #queue do
				if queue[i].op == "ready" then n = n + 1 end
			end
			if n ~= behind then
				behind = n
				show()
			end
		end

		local function held_by_others()
			for _, h in ipairs(holds) do
				if h.fn() then return true end
			end
			return false
		end

		local function pace()
			-- Another feature writes in the buffer (a helpi! answer): the replay waits.
			if paused or held_by_others() then return count_behind() end
			local cps = settings:get("speed")
			-- At most 0.2 s of typing saved up: no burst after a quiet moment.
			if cps > 0 then budget = math.min(budget + cps * POLL_MS / 1000, math.max(cps / 5, 1)) end
			while qhead <= #queue do
				local ev = queue[qhead]
				local n = math.floor(budget)
				if cps == 0 or ev.call == rush or not typed(ev) then
					apply(ev)
					qhead = qhead + 1
				else
					local len = util.runes(ev.text)
					if len > n and n <= 0 then break end
					if len <= n then
						budget = budget - len
						apply(ev)
						qhead = qhead + 1
					else
						-- Type the first n characters; the rest waits for the next tick.
						local b = util.rune_bytes(ev.text, n)
						apply({ op = "text", call = ev.call, key = ev.key, from = ev.from, text = ev.text:sub(1, b) })
						ev.from = ev.from + b
						ev.text = ev.text:sub(b + 1)
						budget = budget - n
						break
					end
				end
			end
			if qhead > #queue then
				queue, qhead = {}, 1
				-- All that pi sent is shown: the run ends, the buffer comes from disk.
				if run_done() then
					local fine, err = pcall(finish)
					if not fine then app.log("error", "symbiosis finish: " .. tostring(err)) end
				end
			end
			count_behind()
		end

		-- ctrl+k space: the replay stops where it is; pi goes on up to the lag limit.
		local function toggle_pause()
			paused = not paused
			show()
		end

		-- ctrl+k .: the rest of this call's preview shows at once, also what pi has
		-- not sent yet. The next call is typed at your speed again.
		local function rush_now()
			rush = active and active.id or (queue[qhead] and queue[qhead].call)
			paused = false
			pace()
			show()
		end

		local function locked(path)
			if run and path == run.path then return true end
			for _, l in ipairs(locks) do
				if l.fn(path) then return true end
			end
			return false
		end

		-- While the replay runs in this file, your typing waits: the buffer is the
		-- replay, and pi has already changed the file on disk. Moves still work.
		app:on("key", function(key)
			if locked(editor.file_path()) and util.changes_buffer(key) then
				if held then ttt.clear_timeout(held) end
				held = ttt.set_timeout(1500, function() held = nil show() end)
				show()
				return true
			end
			return false
		end, 50)

		app:on("tick", pace)
		-- A feature that failed: its holds and locks go.
		app:on("drop", function(owner)
			local function keep(list)
				for i = #list, 1, -1 do
					if list[i].owner == owner then table.remove(list, i) end
				end
			end
			keep(holds)
			keep(locks)
		end)
		app:on("ready", function() show() end)
		channel:heartbeat_field(function(fields)
			fields.pinned = pinned()
			fields.lag = settings:get("lag")
		end)

		app:command({ id = "symbiosis.togglePin", title = "symbiosis: Pin / Unpin the Editor", key = "ctrl+k a", run = toggle_pin })
		app:command({ id = "symbiosis.goToAgent", title = "symbiosis: Go to the Agent's Last Edit", run = go })
		app:command({ id = "symbiosis.slower", title = "symbiosis: Preview Slower", key = "ctrl+k -", run = function() settings:step("speed", -1) end })
		app:command({ id = "symbiosis.faster", title = "symbiosis: Preview Faster", key = "ctrl+k =", run = function() settings:step("speed", 1) end })
		app:command({ id = "symbiosis.pause", title = "symbiosis: Pause / Go On (pi waits)", key = "ctrl+k space", run = toggle_pause })
		app:command({ id = "symbiosis.rush", title = "symbiosis: Show the Rest of the Preview Now", key = "ctrl+k .", run = rush_now })
		app:hint({ key = "ctrl+k a", text = "pin / unpin the editor", order = 30 })
		app:hint({ key = "ctrl+k - / =", text = "preview slower / faster", order = 40 })
		app:hint({ key = "ctrl+k space", text = "pause the replay", order = 50 })
		app:hint({ key = "ctrl+k .", text = "rest of this change at once", order = 60 })

		return {
			show = show,
			finish = finish,
			busy = busy,
			running = function() return run ~= nil end,
			-- The change typed now: {path, regions, at}, or nil.
			typing = function()
				if not (run and active) then return nil end
				return { path = active.path, regions = active.regions, at = run.at }
			end,
			-- The file pi changes now, for the "pi files" panel.
			now_path = function() return run and run.path or (here and here.path) end,
			-- Nothing of the replay is under way for `path`: no call, no queue, no hold.
			quiet = function(path)
				if active or busy(path) or qhead <= #queue or held_by_others() then return false end
				for _, c in pairs(calls) do
					if c.path == path then return false end
				end
				return true
			end,
			-- `fn` belongs to the feature that sets up now: it goes when that one is dropped.
			hold = function(fn) table.insert(holds, { fn = fn, owner = app.current }) end,
			lock = function(fn) table.insert(locks, { fn = fn, owner = app.current }) end,
		}
	end,
}
end
modules["features.sessions"] = function(...)
-- Sessions: each pi writes sessions/<id>.json. The editor follows one of
-- them, the owner: the session whose folder holds the open file (the most
-- recent one if several do), or the one you chose with ctrl+k n. Only the
-- owner writes events and answers helpi!. ctrl+k g goes to its herdr or tmux
-- pane, ctrl+k q stops its turn (stop.json), and the bar says when it waits
-- on a dialog in its own pane.
--
-- Hooks it emits: "sessions" after each refresh (the list or the owner may
-- have changed).
local ttt = require("ttt")
local editor = require("ttt.editor")
local fs = require("ttt.fs")
local json = require("ttt.json")
local system = require("ttt.system")
local util = require("core.util")
local channel_mod = require("core.channel")

local PROTOCOL = channel_mod.PROTOCOL

-- Reads sessions/: the records with a heartbeat in the last 3 seconds.
local function load(dir)
	local list = {}
	local entries = fs.list(dir) or {}
	for _, e in ipairs(entries) do
		if not e.is_dir and e.name:match("%.json$") then
			local raw = fs.read(dir .. "/" .. e.name)
			local ok, rec = pcall(json.decode, raw or "")
			if ok and type(rec) == "table" and rec.id and type(rec.t) == "number" and os.time() - rec.t < 4 then
				table.insert(list, rec)
			end
		end
	end
	-- The name shown: pi's session name (/name), else the folder. When two
	-- sessions would show the same name, the herdr pane (or pid) tells them apart.
	local count = {}
	for _, rec in ipairs(list) do
		rec.folder = rec.name
		if type(rec.title) == "string" and rec.title ~= "" then rec.name = rec.title end
		count[rec.name] = (count[rec.name] or 0) + 1
	end
	for _, rec in ipairs(list) do
		if count[rec.name] > 1 then rec.name = rec.name .. " · " .. (rec.pane or tostring(rec.pid)) end
	end
	table.sort(list, function(a, b)
		if a.name ~= b.name then return a.name < b.name end
		return a.id < b.id
	end)
	return list
end

local function wrote(rec, path)
	if type(rec.files) ~= "table" then return false end
	for _, p in ipairs(rec.files) do
		if p == path then return true end
	end
	return false
end

-- The session the editor follows, for the file at `path`:
--   1. the one you chose (ctrl+k n);
--   2. else the one that wrote or edited the file, the most recent;
--   3. else the one whose folder holds the file, the deepest folder, then the
--      most recent;
--   4. else the most recent one: the editor stays with the agent.
-- Returns the session, and true for 4 (for the status bar), and whether the
-- chosen one is still there.
local function pick(sessions, chosen, path)
	for _, rec in ipairs(sessions) do
		if rec.id == chosen then return rec, false, true end
	end
	local writer, best, latest = nil, nil, nil
	for _, rec in ipairs(sessions) do
		local active = rec.active or 0
		if not latest or active > (latest.active or 0) then latest = rec end
		if path ~= "" and wrote(rec, path) and (not writer or active > (writer.active or 0)) then writer = rec end
		if path ~= "" and util.starts_with(path, rec.cwd .. "/")
			and (not best or #rec.cwd > #best.cwd or (#rec.cwd == #best.cwd and active > (best.active or 0))) then
			best = rec
		end
	end
	if writer or best then return writer or best, false, false end
	return latest, latest ~= nil and path ~= "", false
end

-- The plan step under way, for the session list.
local function now_step(rec)
	if type(rec.plan) ~= "table" then return "" end
	for _, st in ipairs(rec.plan) do
		if st.state == "now" then return " — " .. st.text end
	end
	return ""
end

return {
	name = "sessions",
	pick = pick, -- for the unit tests
	setup = function(app)
		local DIR = app.channel:path("sessions")
		local sessions = {} -- the live pi sessions, by name
		local owner = nil   -- the session the editor follows
		local chosen = nil  -- the id you chose with ctrl+k n; nil = by the open file
		local outside = false -- the owner is only the most recent session, not this file's
		local waiting_said = nil -- the dialog the notice told about
		local go_session

		local function show()
			local text
			if not owner then
				text = "π none"
			else
				local waiting = type(owner.waiting) == "string" and owner.waiting or nil
				-- pi shows a dialog in its own pane: a notice says so for 5 s, then the
				-- bar keeps it.
				if waiting and waiting_said ~= owner.id .. waiting then
					local said = owner.id .. waiting
					waiting_said = said
					ttt.notify("symbiosis: pi " .. owner.name .. " waits for you: " .. waiting .. " (ctrl+k g goes there)", "info")
					-- Measured: here the notice stays (a bare plugin's goes in about 4 s).
					ttt.set_timeout(5000, function()
						if waiting_said == said then ttt.notify("") end
					end)
				elseif not waiting and waiting_said then
					-- The notice goes with the dialog.
					waiting_said = nil
					ttt.notify("")
				end
				text = "π " .. owner.name .. (waiting and " ? waits for you" or owner.working and " ● working" or " ○ idle")
				if owner.version ~= PROTOCOL then text = "π " .. owner.name .. " · old, /reload" end
				if chosen then text = text .. " (chosen)"
				elseif outside then text = text .. " (outside its folder)" end
			end
			ttt.set_status_item("left", "symbiosis.session", text, { priority = 900, on_click = function() go_session() end })
		end

		local function refresh()
			sessions = load(DIR)
			local before = owner and owner.id
			local still
			owner, outside, still = pick(sessions, chosen, editor.file_path() or "")
			if not still then chosen = nil end
			if (owner and owner.id) ~= before then app.channel:heartbeat() end
			app:emit("sessions")
			show()
		end

		-- ctrl+k n: the next session takes over; after the last one, back to "by the open file".
		local function next_session()
			sessions = load(DIR)
			if #sessions == 0 then
				ttt.notify("symbiosis: no pi session is running", "warning")
				return refresh()
			end
			local i = 0
			for k, rec in ipairs(sessions) do
				if rec.id == chosen then i = k end
			end
			local nxt = sessions[i + 1]
			chosen = nxt and nxt.id or nil
			-- No notice: a notice covers the status bar for 4 s, and the bar shows it.
			refresh()
		end

		-- ctrl+k g, or a click on "π ...": go to the owner's pane in herdr or tmux.
		go_session = function()
			if not owner then
				return ttt.notify("symbiosis: no pi session is running", "warning")
			end
			if not owner.pane then
				return ttt.notify("symbiosis: pi " .. owner.name .. " does not run in herdr or tmux", "warning")
			end
			local binary, args = "herdr", { "agent", "focus", owner.pane }
			if owner.host == "tmux" then
				binary, args = "tmux", { "select-window", "-t", owner.pane, ";", "select-pane", "-t", owner.pane }
			end
			local pane = owner.pane
			system.exec_async(binary, args, function(result)
				if result.exit_code ~= 0 then
					ttt.notify("symbiosis: " .. binary .. " could not focus " .. pane .. ": " .. (result.stderr or ""), "error")
				end
			end)
		end

		-- ctrl+k q: stop the owner's turn, as Esc in pi does. pi reads stop.json.
		local stops = 0
		local function stop_pi()
			if not owner then
				return ttt.notify("symbiosis: no pi session is running", "warning")
			end
			if not owner.working then
				return ttt.notify("symbiosis: pi " .. owner.name .. " is idle", "info")
			end
			stops = stops + 1
			app.channel:write_json("stop.json", { id = tostring(os.time()) .. "-" .. stops, to = owner.id })
		end

		app.channel:heartbeat_field(function(fields) fields.owner = owner and owner.id or nil end)
		app:on("ready", refresh)
		app:on("second", refresh)
		app:on("file", refresh)

		app:command({ id = "symbiosis.nextSession", title = "symbiosis: Next pi Session Takes Over", key = "ctrl+k n", run = next_session })
		app:command({ id = "symbiosis.goToSession", title = "symbiosis: Go to the pi Session (herdr, tmux)", key = "ctrl+k g", run = go_session })
		app:command({ id = "symbiosis.stop", title = "symbiosis: Stop pi's Turn", key = "ctrl+k q", run = stop_pi })
		app:hint({ key = "ctrl+k q", text = "stop pi's turn", order = 20 })
		app:hint({ key = "ctrl+k n", text = "next pi session", order = 110 })
		app:hint({ key = "ctrl+k g", text = "go to pi's pane (herdr, tmux)", order = 120 })

		-- In the panel: the sessions; Enter follows one.
		-- ✓ = how the editor picks; ▶ = the session it follows now.
		app:section({
			order = 20,
			render = function(panel)
				panel:label({ text = "pi sessions · Enter: follow it", style = "bold", margin_top = 1 })
				local items = { { id = "", label = (chosen and "  " or "✓ ") .. "automatic: by the open file" } }
				for _, rec in ipairs(sessions) do
					local mark = owner and owner.id == rec.id and "▶ " or "  "
					table.insert(items, {
						id = rec.id,
						label = mark .. rec.name .. (type(rec.waiting) == "string" and " ?" or rec.working and " ●" or " ○")
							.. (type(rec.model) == "string" and (" · " .. rec.model) or "")
							.. (chosen == rec.id and " ✓ chosen" or "") .. now_step(rec),
						muted = rec.version ~= PROTOCOL,
					})
				end
				panel:list({
					items = items,
					truncate_left = false,
					on_command = function(command, node)
						if command ~= "activate" then return end
						chosen = node.id ~= "" and node.id or nil
						refresh()
					end,
				})
			end,
		})

		return {
			PROTOCOL = PROTOCOL,
			owner = function() return owner end,
			list = function() return sessions end,
			refresh = refresh,
		}
	end,
}
end
modules["features.tree"] = function(...)
-- The file tree follows pi: when the editor follows pi into a file, ttt's own
-- file tree opens to it (explorer.revealActiveFile), if the file is in a
-- folder open in ttt. A plugin cannot add a folder to ttt's tree, so the
-- "pi files" panel in the sidebar shows the files of every pi session, by
-- its folder, at any path. While that panel is on screen, the tree is not
-- moved to the explorer: the reveal would take the sidebar away from it.
--
-- Hooks it takes: "sessions" (rebuild), "follow" (path): the editor followed
-- pi into a file.
local ttt = require("ttt")
local editor = require("ttt.editor")
local fs = require("ttt.fs")
local util = require("core.util")

-- Adds `node` under `dir` (a node), in the folder named by `parts`.
local function place(dir, id, parts, node)
	for i = 1, #parts - 1 do
		local part = parts[i]
		dir.by = dir.by or {}
		local sub = dir.by[part]
		if not sub then
			sub = { id = id .. "/" .. table.concat(parts, "/", 1, i), label = part .. "/", expanded = true, children = {} }
			dir.by[part] = sub
			table.insert(dir.children, sub)
		end
		dir = sub
	end
	table.insert(dir.children, node)
end

-- Folders first, then files, by name; and drops the lookup tables.
local function tidy(node)
	node.by = nil
	if not node.children then return end
	table.sort(node.children, function(a, b)
		local ad, bd = a.children ~= nil, b.children ~= nil
		if ad ~= bd then return ad end
		return a.label < b.label
	end)
	for _, child in ipairs(node.children) do tidy(child) end
end

-- The tree: one node for each session ("▶" = the one the editor follows),
-- its files under its folder; a file outside the folder goes under its own
-- folder, by full path. "✎" marks the file pi changes now (`now`).
local function build(sessions, owner, now)
	local items, paths = {}, {}
	for _, rec in ipairs(sessions) do
		local followed = owner and owner.id == rec.id
		local node = {
			id = rec.id,
			label = (followed and "▶ " or "") .. rec.name,
			badge = util.short(rec.cwd or ""),
			expanded = true,
			children = {},
		}
		local seen = {}
		for _, path in ipairs(type(rec.files) == "table" and rec.files or {}) do
			if type(path) == "string" and not seen[path] then
				seen[path] = true
				local id = rec.id .. "|" .. path
				paths[id] = path
				local file = { id = id, label = util.name(path), icon = (followed and path == now) and "✎" or " " }
				if rec.cwd and util.starts_with(path, rec.cwd .. "/") then
					place(node, rec.id, util.split_path(path:sub(#rec.cwd + 2)), file)
				else
					place(node, rec.id, { util.short(util.parent(path)), util.name(path) }, file)
				end
			end
		end
		if #node.children == 0 then
			node.children = { { id = rec.id .. "|none", label = "no files changed yet", muted = true } }
		end
		tidy(node)
		table.insert(items, node)
	end
	return items, paths
end

return {
	name = "tree",
	needs = { "sessions" },
	build = build, -- for the unit tests
	setup = function(app)
		local sessions = app:need("sessions")
		local seen = -100  -- the tick when ttt last drew the "pi files" panel
		local items = {}   -- the "pi files" tree, built when the sessions or the follow change
		local paths = {}   -- node id -> file path
		local revealed = nil -- the file last shown in ttt's file tree

		local function rebuild()
			-- The file pi changes now: the replay's, when there is a replay.
			local replay = app:get("replay")
			local now = replay and replay.now_path() or nil
			items, paths = build(sessions.list(), sessions.owner(), now)
		end

		-- After the editor followed pi into `path`.
		local function follow(path)
			rebuild()
			-- ttt draws the panel on each tick while it is on screen.
			if app.ticks - seen <= 12 then return end
			if path == revealed then return end
			revealed = path
			-- ttt.fs sees only the folders open in ttt (and the plugin's folder): so
			-- this says if the file is in ttt's tree. Outside it, the reveal would
			-- only show "File is not in the explorer".
			if editor.file_path() == path and fs.exists(path) then
				ttt.exec_command("explorer.revealActiveFile")
			end
		end

		app:on("sessions", rebuild)
		app:on("follow", follow)
		app:sidebar({
			title = "pi files",
			render = function(panel)
				seen = app.ticks
				if #items == 0 then
					panel:label({ text = "No pi session is running.", style = "muted" })
					return
				end
				panel:tree({
					items = items,
					on_select = function(node)
						local path = paths[node.id]
						if path then ttt.open_file(path) end
					end,
				})
			end,
		})
		app:note("Sidebar: the \"pi files\" tab lists pi's files", 10)
		return { follow = follow }
	end,
}
end
modules["main"] = function(...)
-- symbiosis, the ttt side: the plugin's entry. ttt runs one file per plugin
-- and lets it require only its own modules (ttt, ttt.editor, ...), so the
-- sources in ttt/src are bundled into ttt/symbiosis/plugin.lua by
-- ttt/build.ts. See ttt/README.md for how to write a feature.
--
-- pi (the extension in pi/) appends events to events.jsonl in the plugin
-- folder; the features read them through the channel (core/channel.lua):
--   sessions  the pi sessions; the one the editor follows (the owner)
--   plan      pi's plan in the status bar, ctrl+k v
--   tree      the "pi files" sidebar
--   replay    pi's writes and edits typed in the buffer, at your speed
--   marks     the gutter: ▌ on the change typed now, π on its line
--   autosave  saves your file a while after you type
--   helpi     a comment that ends in `helpi!` asks pi
--   changes   ctrl+k w: what pi changed in its last turn
--   panel     ctrl+k h: settings, sessions, keys
-- See docs/design.md.
local app = require("core.app").new()

app:use("features.sessions")
app:use("features.plan")
app:use("features.tree")
app:use("features.replay")
app:use("features.marks")
app:use("features.autosave")
app:use("features.helpi")
app:use("features.changes")
app:use("features.panel")

app:start()
end
require("main")
